'use strict';

/* eslint-disable max-lines */

// MODULES //

var acornParse = require( 'acorn' ).parse;
var walkSimple = require( 'acorn-walk' ).simple;
var analyzeScope = require( 'eslint-scope' ).analyze;
var isNodeBuiltinSpecifier = require( '@stdlib/assert/is-node-builtin' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var format = require( '@stdlib/string/format' );
var resolve = require( './resolve_stdlib_esm.js' );


// VARIABLES //

var FORBIDDEN_GLOBALS = {
	'Buffer': 'unsupported-node-global',
	'__dirname': 'unsupported-node-global',
	'__filename': 'unsupported-node-global',
	'exports': 'unsupported-commonjs-global',
	'global': 'unsupported-node-global',
	'module': 'unsupported-commonjs-global',
	'process': 'unsupported-node-global'
};

var WORKER_FORBIDDEN_GLOBALS = {
	'Audio': true,
	'Element': true,
	'HTMLCanvasElement': true,
	'HTMLElement': true,
	'Image': true,
	'IntersectionObserver': true,
	'MutationObserver': true,
	'Node': true,
	'ResizeObserver': true,
	'SVGElement': true,
	'alert': true,
	'cancelAnimationFrame': true,
	'confirm': true,
	'customElements': true,
	'document': true,
	'getComputedStyle': true,
	'localStorage': true,
	'prompt': true,
	'requestAnimationFrame': true,
	'sessionStorage': true,
	'window': true
};


// FUNCTIONS //

/**
* Returns a failed lowering result.
*
* @private
* @param {string} code - failure code
* @param {string} message - failure message
* @param {Object} [details] - details
* @returns {Object} result
*/
function failure( code, message, details ) {
	return {
		'ok': false,
		'code': code,
		'message': message,
		'details': details || {}
	};
}

/**
* Parses JavaScript according to the target's advertised syntax level.
*
* @private
* @param {string} code - source
* @returns {Object} AST
*/
function parse( code ) {
	return acornParse( code, {
		'allowHashBang': false,
		'ecmaVersion': 2017, // NOTE: ES2017 matches JupyterLite's JavaScript kernel's advertised `language_info.version`, and thus we make it consistent here. Should the kernel update the advertised version, we should update here and elsewhere, as well.
		'locations': true,
		'ranges': true,
		'sourceType': 'module'
	});
}

/**
* Returns an eslint scope manager.
*
* @private
* @param {Object} ast - AST
* @returns {Object} scope manager
*/
function scopes( ast ) {
	return analyzeScope( ast, {
		'ecmaVersion': 2017, // NOTE: ES2017 matches JupyterLite's JavaScript kernel's advertised `language_info.version`, and thus we make it consistent here. Should the kernel update the advertised version, we should update here and elsewhere, as well.
		'sourceType': 'module'
	});
}

/**
* Returns unresolved references from the global scope.
*
* @private
* @param {Object} manager - scope manager
* @returns {Array} references
*/
function freeReferences( manager ) {
	return manager.globalScope.through;
}

/**
* Returns the variable defined by a declarator.
*
* @private
* @param {Object} manager - scope manager
* @param {Object} declarator - declarator
* @returns {(Object|null)} variable
*/
function variable( manager, declarator ) {
	var variables;
	var defs;
	var i;
	var j;
	var k;

	for ( i = 0; i < manager.scopes.length; i++ ) {
		variables = manager.scopes[ i ].variables;
		for ( j = 0; j < variables.length; j++ ) {
			defs = variables[ j ].defs;
			for ( k = 0; k < defs.length; k++ ) {
				if ( defs[ k ].node === declarator ) {
					return variables[ j ];
				}
			}
		}
	}
	return null;
}

/**
* Tests whether a specifier names a Node.js builtin.
*
* @private
* @param {string} specifier - specifier
* @returns {boolean} boolean
*/
function isNodeBuiltin( specifier ) {
	return specifier.slice( 0, 5 ) === 'node:' || isNodeBuiltinSpecifier( specifier );
}

/**
* Encodes a JavaScript single-quoted string literal.
*
* @private
* @param {string} value - value
* @returns {string} literal
*/
function quote( value ) {
	var code;
	var out;
	var hex;
	var ch;
	var i;

	out = "'";
	for ( i = 0; i < value.length; i++ ) {
		ch = value.charAt( i );
		code = value.charCodeAt( i );
		if ( ch === '\\' ) {
			out += '\\\\';
		} else if ( ch === "'" ) {
			out += "\\'";
		} else if ( code <= 31 || ( code >= 127 && code <= 159 ) ) {
			hex = code.toString( 16 );
			out += '\\x'+( '0'+hex ).slice( -2 );
		} else if ( code === 0x2028 || code === 0x2029 ) {
			hex = code.toString( 16 );
			out += '\\u'+( '000'+hex ).slice( -4 );
		} else {
			out += ch;
		}
	}
	return out+"'";
}

/**
* Returns transform provenance shared by require and import rewrites.
*
* @private
* @param {Object} resolution - resolution record
* @param {string} specifier - authored specifier
* @returns {Object} transform fields
*/
function provenance( resolution, specifier ) {
	var out = {
		'export': resolution.export,
		'resolver_source': resolution.resolverSource,
		'resolver_version': resolution.resolverVersion,
		'specifier': specifier,
		'url': resolution.url,
		'url_mutable': resolution.mutable
	};
	if ( resolution.repository ) {
		out.repository = resolution.repository;
	}
	return out;
}

/**
* Validates a selected CommonJS binding.
*
* @private
* @param {Object} manager - scope manager
* @param {Object} declarator - declarator
* @param {Object} declaration - declaration
* @returns {(Object|null)} failure
*/
function validateBinding( manager, declarator, declaration ) {
	var binding;
	var ref;
	var i;

	binding = variable( manager, declarator );
	if ( !binding || binding.defs.length !== 1 ) {
		return failure( 'unsafe-binding', 'CommonJS local binding is redeclared or collides with another declaration.' );
	}
	for ( i = 0; i < binding.references.length; i++ ) {
		ref = binding.references[ i ];
		if ( !ref.init && ref.identifier.start < declaration.start ) {
			return failure( 'binding-read-before-import', 'CommonJS local binding is read before its declaration.' );
		}
		if ( !ref.init && ref.isWrite() ) {
			return failure( 'mutable-import-binding', 'CommonJS local binding is written after initialization.' );
		}
	}
	return null;
}

/**
* Validates an authored import binding.
*
* @private
* @param {Object} manager - scope manager
* @param {Object} specifier - import specifier
* @returns {(Object|null)} failure
*/
function validateImportBinding( manager, specifier ) {
	var binding;
	var i;

	binding = variable( manager, specifier );
	if ( !binding || binding.defs.length !== 1 ) {
		return failure( 'unsafe-binding', 'Imported local binding is redeclared or collides with another declaration.' );
	}
	for ( i = 0; i < binding.references.length; i++ ) {
		if ( binding.references[ i ].isWrite() ) {
			return failure( 'mutable-import-binding', 'Imported local binding is written after declaration.' );
		}
	}
	return null;
}

/**
* Creates a rewrite for a CommonJS declaration.
*
* @private
* @param {Object} declaration - declaration
* @param {Object} declarator - declarator
* @param {Object} resolution - resolution record
* @param {string} specifier - authored specifier
* @param {string} code - source
* @returns {Object} rewrite
*/
function requireRewrite( declaration, declarator, resolution, specifier, code ) { // eslint-disable-line max-len
	var replacement;
	var transform;
	var local;

	local = declarator.id.name;
	if ( resolution.export === 'default' ) {
		replacement = format( 'import %s from %s;', local, quote( resolution.url ) );
	} else {
		replacement = format( 'import * as %s from %s;', local, quote( resolution.url ) );
	}
	transform = provenance( resolution, specifier );
	transform.kind = 'stdlib-cjs-to-esm';
	transform.local = local;
	transform.original = code.slice( declaration.start, declaration.end );
	transform.range = [ declaration.start, declaration.end ];
	transform.replacement = replacement;
	return {
		'start': declaration.start,
		'end': declaration.end,
		'replacement': replacement,
		'transform': transform
	};
}

/**
* Creates a rewrite for an authored static import.
*
* @private
* @param {Object} node - import declaration
* @param {Object} resolution - resolution record
* @param {string} specifier - authored specifier
* @param {string} code - source
* @returns {Object} rewrite
*/
function importRewrite( node, resolution, specifier, code ) {
	var replacement = quote( resolution.url );
	var transform = provenance( resolution, specifier );
	var local = node.specifiers[ 0 ].local.name;

	transform.kind = 'module-specifier-to-url';
	transform.local = local;
	transform.original = code.slice( node.source.start, node.source.end );
	transform.range = [ node.source.start, node.source.end ];
	transform.replacement = replacement;
	return {
		'start': node.source.start,
		'end': node.source.end,
		'replacement': replacement,
		'transform': transform
	};
}

/**
* Checks free global references against a target runtime.
*
* @private
* @param {Array} refs - free references
* @param {string} runtime - runtime
* @param {Object} selectedRequire - selected require identifiers
* @returns {(Object|null)} failure
*/
function checkGlobals( refs, runtime, selectedRequire ) {
	var name;
	var ref;
	var i;

	for ( i = 0; i < refs.length; i++ ) {
		ref = refs[ i ];
		name = ref.identifier.name;
		if ( name === 'require' && !selectedRequire[ ref.identifier.start ] ) {
			return failure( 'residual-require', 'Code contains a CommonJS require reference which cannot be lowered safely.' );
		}
		if ( FORBIDDEN_GLOBALS[ name ] ) {
			return failure( FORBIDDEN_GLOBALS[ name ], format( 'Code references the unsupported free global `%s`.', name ) );
		}
		if ( runtime === 'worker' && WORKER_FORBIDDEN_GLOBALS[ name ] ) {
			return failure( 'unsupported-worker-global', format( 'Web Worker code references the main-thread global `%s`.', name ) );
		}
	}
	return null;
}

/**
* Compares rewrites in descending source order.
*
* @private
* @param {Object} a - first rewrite
* @param {Object} b - second rewrite
* @returns {number} comparison result
*/
function descending( a, b ) {
	return b.start - a.start;
}

/**
* Compares transforms in ascending source order.
*
* @private
* @param {Object} a - first transform
* @param {Object} b - second transform
* @returns {number} comparison result
*/
function ascending( a, b ) {
	return a.range[ 0 ] - b.range[ 0 ];
}


// MAIN //

/**
* Lowers and checks one JavaScript cell for a JupyterLite runtime.
*
* @private
* @param {string} code - source code
* @param {Object} options - converter options
* @param {string} runtime - runtime
* @returns {Object} lowering result
*/
function lower( code, options, runtime ) {
	var selectedRequire;
	var freeReference;
	var declaration;
	var transforms;
	var exportType;
	var importType;
	var declarator;
	var resolution;
	var specifier;
	var rewrites;
	var manager;
	var binding;
	var lowered;
	var result;
	var free;
	var node;
	var ast;
	var i;

	try {
		ast = parse( code );
		manager = scopes( ast );
	} catch ( err ) {
		return failure( 'javascript-parse-error', 'JavaScript is not valid module source.', {
			'message': err.message
		});
	}
	transforms = [];
	rewrites = [];

	selectedRequire = Object.create( null );
	freeReference = Object.create( null );
	free = freeReferences( manager );
	for ( i = 0; i < free.length; i++ ) {
		freeReference[ free[ i ].identifier.start ] = true;
	}
	result = null;
	walkSimple( ast, {
		'ExportAllDeclaration': unsupportedExport,
		'ExportDefaultDeclaration': unsupportedExport,
		'ExportNamedDeclaration': unsupportedExport
	});
	if ( result ) {
		return result;
	}
	for ( i = 0; i < ast.body.length; i++ ) {
		node = ast.body[ i ];
		if ( node.type === 'VariableDeclaration' ) {
			if ( node.declarations.length !== 1 ) {
				continue;
			}
			declarator = node.declarations[ 0 ];
			if (
				declarator.id.type !== 'Identifier' ||
				!declarator.init ||
				declarator.init.type !== 'CallExpression' ||
				declarator.init.callee.type !== 'Identifier' ||
				declarator.init.callee.name !== 'require' ||
				declarator.init.arguments.length !== 1 ||
				declarator.init.arguments[ 0 ].type !== 'Literal' ||
				!isString( declarator.init.arguments[ 0 ].value )
			) {
				continue;
			}
			declaration = node;
			specifier = declarator.init.arguments[ 0 ].value;
			if ( !freeReference[ declarator.init.callee.start ] ) {
				return failure( 'shadowed-require', 'The CommonJS require identifier is locally bound or modified.' );
			}
			if ( isNodeBuiltin( specifier ) ) {
				return failure( 'unsupported-node-builtin', 'Node.js builtin modules are unavailable in the browser kernel.', {
					'specifier': specifier
				});
			}
			resolution = resolve( specifier, options, runtime );
			if ( !resolution.ok ) {
				return failure( resolution.code, resolution.message, {
					'specifier': specifier
				});
			}
			binding = validateBinding( manager, declarator, declaration );
			if ( binding ) {
				return binding;
			}
			selectedRequire[ declarator.init.callee.start ] = true;
			rewrites.push( requireRewrite( declaration, declarator, resolution.record, specifier, code ) ); // eslint-disable-line max-len
		} else if ( node.type === 'ImportDeclaration' ) {
			if ( node.specifiers.length !== 1 ) {
				return failure( 'unsupported-import-form', 'Only one default or namespace import is supported.' );
			}
			specifier = node.source.value;
			if ( isNodeBuiltin( specifier ) ) {
				return failure( 'unsupported-node-builtin', 'Node.js builtin modules are unavailable in the browser kernel.', {
					'specifier': specifier
				});
			}
			resolution = resolve( specifier, options, runtime );
			if ( !resolution.ok ) {
				return failure( resolution.code, resolution.message, {
					'specifier': specifier
				});
			}
			importType = node.specifiers[ 0 ].type;
			exportType = resolution.record.export;
			if (
				( importType === 'ImportDefaultSpecifier' && exportType !== 'default' ) ||
				( importType === 'ImportNamespaceSpecifier' && exportType !== 'namespace' ) ||
				( importType !== 'ImportDefaultSpecifier' && importType !== 'ImportNamespaceSpecifier' )
			) {
				return failure( 'import-export-mismatch', 'Authored import form does not match the resolved module export shape.' );
			}
			binding = validateImportBinding( manager, node.specifiers[ 0 ] );
			if ( binding ) {
				return binding;
			}
			rewrites.push( importRewrite( node, resolution.record, specifier, code ) ); // eslint-disable-line max-len
		}
	}
	result = checkGlobals( free, runtime, selectedRequire );
	if ( result ) {
		return result;
	}
	rewrites.sort( descending );
	lowered = code;
	for ( i = 0; i < rewrites.length; i++ ) {
		lowered = lowered.slice( 0, rewrites[i].start ) + rewrites[i].replacement + lowered.slice( rewrites[i].end ); // eslint-disable-line max-len
		transforms.push( rewrites[ i ].transform );
	}
	transforms.sort( ascending );
	try {
		manager = scopes( parse( lowered ) );
	} catch ( err ) {
		return failure( 'lowered-parse-error', 'Lowered JavaScript is not valid module source.', {
			'message': err.message
		});
	}
	free = freeReferences( manager );
	result = checkGlobals( free, runtime, Object.create( null ) );
	if ( result && result.code === 'residual-require' ) {
		return result;
	}
	return {
		'ok': true,
		'code': lowered,
		'transforms': transforms
	};

	/**
	* Records an unsupported export declaration.
	*
	* @private
	* @returns {void}
	*/
	function unsupportedExport() {
		result = failure( 'unsupported-export', 'Export declarations are not supported in executable notebook cells.' );
	}
}


// EXPORTS //

module.exports = lower;
